import sys

data = sys.stdin.read().split()
target, start, n = int(data[0]), int(data[1]), int(data[2])
pos = [int(data[3 + 2 * i]) for i in range(n)]
fuel = [int(data[4 + 2 * i]) for i in range(n)]
best = -1
for mask in range(1 << n):
    if mask & (mask >> 1):
        continue
    reach = start
    ok = True
    for i in range(n):
        if mask >> i & 1:
            if reach < pos[i]:
                ok = False
                break
            reach += fuel[i]
    if ok and reach >= target:
        c = bin(mask).count("1")
        if best == -1 or c < best:
            best = c
print(best)

